 if(isset($_POST['reimportar_menu'])){srnu_sembrar_catalogo_menu($pdo,true);ego('catalogo.php?menu=actualizado');}
 if(isset($_POST['guardar'])){$id=(int)($_POST['id']??0);$tipo=in_array($_POST['tipo_entrega']??'inmediata',['inmediata','sobre_pedido'],true)?$_POST['tipo_entrega']:'inmediata';$dias=$tipo==='sobre_pedido'?eint('dias_entrega_estimada'):0;$garRaw=trim((string)($_POST['garantia_meses']??''));$garantia=max(0,(int)$garRaw);if($tipo==='sobre_pedido'&&$garantia<=0)$garantia=12;$fotoActual='';if($id>0){$sf=$pdo->prepare('SELECT foto_producto FROM catalogo_servicios WHERE id=?');$sf->execute([$id]);$fotoActual=(string)($sf->fetchColumn()?:'');}if(!empty($_POST['quitar_foto']))$fotoActual='';$foto=srnu_guardar_foto_producto_upload($_FILES['foto_producto']??['error'=>UPLOAD_ERR_NO_FILE],$fotoActual?:null);$data=[epost('nombre'),epost('descripcion'),epost('categoria'),efloat('precio_base'),efloat('costo_base'),isset($_POST['sergio'])?1:0,isset($_POST['ricardo'])?1:0,isset($_POST['tomas'])?1:0,$garantia,$tipo,$dias,$foto];if($data[0]!==''){if($id>0){$pdo->prepare('UPDATE catalogo_servicios SET nombre=?,descripcion=?,categoria=?,precio_base=?,costo_base=?,responsable_sergio=?,responsable_ricardo=?,responsable_tomas=?,garantia_meses=?,tipo_entrega=?,dias_entrega_estimada=?,foto_producto=?,dias_trabajo_min=0,dias_trabajo_max=0,activo=1 WHERE id=?')->execute([...$data,$id]);}else{$pdo->prepare('INSERT INTO catalogo_servicios(nombre,descripcion,categoria,precio_base,costo_base,responsable_sergio,responsable_ricardo,responsable_tomas,garantia_meses,tipo_entrega,dias_entrega_estimada,foto_producto,dias_trabajo_min,dias_trabajo_max,activo) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,0,0,1)')->execute($data);}}}
 if(isset($_POST['toggle']))$pdo->prepare('UPDATE catalogo_servicios SET activo=IF(activo=1,0,1) WHERE id=?')->execute([(int)$_POST['id']]);
 ego('catalogo.php'.(!empty($_POST['id'])?'?edit='.(int)$_POST['id']:''));
}
$editId=(int)($_GET['edit']??0);$edit=null;if($editId){$s=$pdo->prepare('SELECT * FROM catalogo_servicios WHERE id=?');$s->execute([$editId]);$edit=$s->fetch()?:null;}
$rows=$pdo->query('SELECT cs.*, (SELECT COUNT(*) FROM catalogo_insumos ci WHERE ci.catalogo_id=cs.id) insumos FROM catalogo_servicios cs ORDER BY activo DESC,nombre')->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catálogo · SRNU</title><link rel="icon" href="favicon.png"><?=srnu_ui_head()?><style>.w{max-width:1450px;margin:auto}.form-grid{display:grid;grid-template-columns:2fr 2fr repeat(5,minmax(120px,1fr));gap:10px}.checks{display:flex;gap:14px;align-items:center;flex-wrap:wrap}.badge-order{padding:5px 9px;border-radius:999px;background:#fff7ed;color:#9a3412;font-weight:800}.badge-now{padding:5px 9px;border-radius:999px;background:#ecfdf5;color:#166534;font-weight:800}.badge-fixed{display:inline-block;margin-top:5px;padding:4px 8px;border-radius:999px;background:#e8efff;color:#174ea6;font-weight:900;font-size:11px}.menu-note{padding:12px 14px;border-radius:12px;background:#eef4ff;border:1px solid #cbdcff;color:#173b73;margin:0 0 14px}@media(max-width:900px){.form-grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){.form-grid{grid-template-columns:1fr}}</style></head><body><?php srnu_appbar('catalogo');?><main class="w"><div class="srnu-page-heading"><div><h1>Catálogo de servicios y productos</h1><p>Precios, costos, responsables, garantía y disponibilidad operativa.</p></div><div class="actions"><a class="btn blue" href="plantillas.php">Plantillas de paquetes</a><form method="post" style="display:inline"><button class="btn light" name="reimportar_menu" value="1">Restaurar precios fijos del menú</button></form></div></div><?php if(isset($_GET['menu'])):?><div class="menu-note">Precios fijos del menú SRNU actualizados en el catálogo.</div><?php endif;?><section class="panel" style="padding:18px;margin-bottom:16px">
<h2 style="margin:0 0 6px;font-size:18px">Artículos de cotizaciones anteriores</h2>
<p style="margin:0 0 12px">Recupera productos y servicios con su foto, precio unitario, costo, garantía y responsables. Se respetan los datos de los artículos que ya existen.</p>
