<div id="catalogo-recuperar-estado" role="status" aria-live="polite" style="margin-top:10px"></div>
<?php if(isset($_GET['recuperados'])): ?><p class="menu-note" style="margin-top:12px"><?=(int)$_GET['recuperados']?> artículo(s) nuevo(s) recuperado(s). Puedes reutilizarlos desde cualquier cotización.</p><?php endif; ?>
</section><section class="panel" style="padding:20px"><form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="form-grid"><input name="nombre" placeholder="Nombre" required value="<?=eh($edit['nombre']??'')?>"><input name="descripcion" placeholder="Descripción" value="<?=eh($edit['descripcion']??'')?>"><input name="categoria" placeholder="Categoría" value="<?=eh($edit['categoria']??'')?>"><input type="number" step="0.01" name="precio_base" placeholder="Precio" value="<?=eh($edit['precio_base']??'')?>"><input type="number" step="0.01" name="costo_base" placeholder="Costo interno" value="<?=eh($edit['costo_base']??'')?>"><input type="number" id="garantia_meses" name="garantia_meses" min="0" placeholder="Garantía meses" title="Sobre pedido: 12 meses por defecto" value="<?=eh($edit['garantia_meses']??0)?>"><select name="tipo_entrega" id="tipo_entrega"><option value="inmediata" <?=($edit['tipo_entrega']??'inmediata')==='inmediata'?'selected':''?>>Entrega inmediata</option><option value="sobre_pedido" <?=($edit['tipo_entrega']??'')==='sobre_pedido'?'selected':''?>>Sobre pedido</option></select><input type="number" name="dias_entrega_estimada" id="dias_entrega" min="0" placeholder="Días llegada piezas" title="Tiempo aproximado para que lleguen las piezas" value="<?=eh($edit['dias_entrega_estimada']??0)?>"></div><div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-top:12px"><label style="font-weight:800">Fotografía del producto <input type="file" name="foto_producto" accept="image/jpeg,image/png,image/webp" style="margin-left:8px"></label><?php if(!empty($edit['foto_producto'])):?><img src="<?=eh($edit['foto_producto'])?>" alt="Foto" style="width:92px;height:68px;object-fit:cover;border-radius:12px;border:1px solid #dbe4ef"><label><input type="checkbox" name="quitar_foto" value="1"> Quitar foto</label><?php endif;?></div><div class="checks" style="margin-top:12px"><strong>Responsables:</strong><label><input type="checkbox" name="sergio" <?=!empty($edit['responsable_sergio'])?'checked':''?>> Sergio</label><label><input type="checkbox" name="ricardo" <?=!empty($edit['responsable_ricardo'])?'checked':''?>> Ricardo</label><label><input type="checkbox" name="tomas" <?=!empty($edit['responsable_tomas'])?'checked':''?>> Tomás</label><button class="btn blue" name="guardar" value="1"><?=$edit?'Actualizar':'Guardar'?></button><?php if($edit):?><a class="btn light" href="catalogo.php">Cancelar</a><?php endif;?></div></form></section><section class="tablebox" style="margin-top:16px"><table><thead><tr><th>Servicio / producto</th><th>Categoría</th><th>Foto</th><th>Disponibilidad</th><th>Precio</th><th>Costo</th><th>Responsables</th><th>Garantía</th><th>Insumos</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr style="<?=$r['activo']?'':'opacity:.5'?>"><td><b><?=eh($r['nombre'])?></b><div class="small"><?=eh($r['descripcion'])?></div><?php if(!empty($r['precio_fijo'])):?><span class="badge-fixed">PRECIO FIJO · MENÚ SRNU</span><?php endif;?></td><td><?=eh($r['categoria']?:'—')?></td><td><?php if(!empty($r['foto_producto'])):?><img src="<?=eh($r['foto_producto'])?>" alt="<?=eh($r['nombre'])?>" style="width:82px;height:60px;object-fit:cover;border-radius:10px;border:1px solid #dbe4ef"><?php else:?><span class="small">Sin foto</span><?php endif;?></td><td><?php if($r['tipo_entrega']==='sobre_pedido'):?><span class="badge-order">Sobre pedido</span><div class="small">Llegada: <?= (int)$r['dias_entrega_estimada']?> días aprox.</div><?php else:?><span class="badge-now">Entrega inmediata</span><?php endif;?></td><td><?=emoney($r['precio_base'])?></td><td><?=emoney($r['costo_base'])?></td><td><?= $r['responsable_sergio']?'Sergio ':''?><?= $r['responsable_ricardo']?'Ricardo ':''?><?= $r['responsable_tomas']?'Tomás':''?></td><td><?=(int)$r['garantia_meses']?> meses</td><td><a href="receta.php?id=<?=(int)$r['id']?>"><?=(int)$r['insumos']?> insumo(s)</a></td><td><a class="btn light" href="?edit=<?=(int)$r['id']?>">Editar</a><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button name="toggle" value="1" class="btn <?=$r['activo']?'danger':'green'?>"><?=$r['activo']?'Desactivar':'Activar'?></button></form></td></tr><?php endforeach;?></tbody></table></section></main><script>const t=document.getElementById('tipo_entrega'),d=document.getElementById('dias_entrega'),g=document.getElementById('garantia_meses');function sync(){const sp=t.value==='sobre_pedido';if(d)d.style.display=sp?'':'none';if(!sp&&d)d.value=0;if(sp&&g){const m=parseInt(g.value||'0',10);if(!Number.isFinite(m)||m<=0)g.value=12;}}t.addEventListener('change',sync);sync();</script><script>
document.getElementById('catalogo-recuperar').addEventListener('click',async function(){
 const boton=this, estado=document.getElementById('catalogo-recuperar-estado');
 boton.disabled=true;boton.textContent='Recuperando artículos…';
 let cursor=0,creados=0,procesados=0;
 try{
  let pendientes=true;
  while(pendientes){
   const datos=new FormData();datos.set('token',<?=json_encode($_SESSION['catalogo_recuperar_token'])?>);datos.set('cursor',String(cursor));
   const respuesta=await fetch('catalogo_recuperar.php',{method:'POST',body:datos,credentials:'same-origin'});
   const lote=await respuesta.json();if(!respuesta.ok||!lote.ok)throw new Error(lote.error||'No se pudo recuperar el catálogo.');
   creados+=Number(lote.creados)||0;procesados+=Number(lote.procesados)||0;
   estado.textContent=procesados+' artículos revisados · '+creados+' nuevos en catálogo.';
   pendientes=!!lote.pendientes;
   if(pendientes&&(!lote.cursor||Number(lote.cursor)===cursor))throw new Error('Se detuvo la recuperación. Puedes volver a intentarlo.');
   cursor=Number(lote.cursor)||0;
  }
  window.location.href='catalogo.php?recuperados='+encodeURIComponent(creados);
 }catch(error){
  estado.textContent=error.message+' Los artículos ya recuperados se conservan. Puedes reintentar sin duplicarlos.';
  boton.disabled=false;boton.textContent='Reintentar recuperación';
 }
});
</script></body></html>
